        ctx.beginPath();
        ctx.moveTo(0, 0);
        ctx.lineTo(ox, oy);
        ctx.lineTo(ox + length, oy);
        ctx.lineTo(ox + length - 5, oy + 10);
        ctx.lineTo(ox - 5, oy + 10);
        ctx.closePath();
        ctx.fill();
        ctx.stroke();
        ctx.restore();
